    const valIncome = document.getElementById('val-income');
    const result = document.getElementById('result');

    function updateCalculation() {
        const income = parseFloat(sliderIncome.value);
        const rate = parseFloat(selectRate.value);
        const tax = income * rate;

        // 更新显示
        valIncome.textContent = income;
        dispIncome.textContent = income;
        dispRate.textContent = (rate * 100) + "%";
