        <path d="M100 50 L300 50 L250 200 L150 200 Z" fill="#e2e8f0" stroke="#94a3b8" />
        <path d="M150 200 L250 200 L200 350 Z" fill="#e2e8f0" stroke="#94a3b8" />

        <!-- 扣除标准块 -->
        <rect id="deduction" x="120" y="100" width="160" height="40" fill="#f59e0b" rx="5" style="cursor: pointer;" />
        <text x="200" y="125" text-anchor="middle" class="label" fill="white">扣除标准</text>

