        <!-- 计税基数区域 -->
        <rect id="taxBase" x="175" y="250" width="50" height="80" fill="#10b981" opacity="0" />
        <text id="baseLabel" x="200" y="295" text-anchor="middle" class="label" opacity="0">计税基数</text>
    </svg>

    <div class="controls">
        <button id="btnDirect">直接计算税额</button>
        <button id="btnFilter">应用扣除标准</button>
    </div>
</div>

<script>
    const msg = document.getElementById('msg');
    const deduction = document.getElementById('deduction');
    const taxBase = document.getElementById('taxBase');
    const baseLabel = document.getElementById('baseLabel');
