    <p style="text-align: center;">点击下方数字，观察它们如何影响应纳税基数：</p>

    <div class="formula-box">
        <div id="total" class="num-box">6000</div>
        <span>-</span>
        <div id="taxFree" class="num-box">2000</div>
        <span>=</span>
        <div id="result">4000</div>
    </div>

    <div class="controls">
        <button id="resetBtn">重置演示</button>
    </div>

    <p id="hint" style="text-align: center; color: #64748b; margin-top: 2rem;">提示：请点击“总收入”和“免税额”来完成计算。</p>
</div>

<script>
    const totalEl = document.getElementById('total');
    const taxFreeEl = document.getElementById('taxFree');
    const resultEl = document.getElementById('result');
    const resetBtn = document.getElementById('resetBtn');
    const hintEl = document.getElementById('hint');

    let clicked = { total: false, taxFree: false };

    function update() {
        if (clicked.total && clicked.taxFree) {
            resultEl.style.opacity = '1';
            resultEl.classList.add('highlight');
            hintEl.innerText = '计算完成！4000元即为我们需要的“计税基数”。';
        }
    }

    totalEl.addEventListener('click', () => {
        totalEl.classList.add('active');
        clicked.total = true;
        update();
    });

    taxFreeEl.addEventListener('click', () => {
        taxFreeEl.classList.add('active');
        clicked.taxFree = true;
        update();
    });

    resetBtn.addEventListener('click', () => {
        clicked = { total: false, taxFree: false };
        totalEl.classList.remove('active');
        taxFreeEl.classList.remove('active');
        resultEl.style.opacity = '0';
        resultEl.classList.remove('highlight');
        hintEl.innerText = '提示：请点击“总收入”和“免税额”来完成计算。';
    });
</script>

</body>
